SELECT r.id, r.tenant_id, r.role_code, r.role_name, r.description, r.priority, r.status, r.version, r.created_at, r.updated_at FROM iam_role r JOIN iam_user_role ur ON ur.role_id = r.id WHERE ur.user_id = #{userId} AND ur.status = 'ACTIVE' AND ur.active_slot = 1 AND r.delete_marker = 0
AND ur.tenant_id = #{tenantId}
ORDER BY r.priority DESC, r.id ASC

SELECT u.id, u.tenant_id, u.username, u.display_name, u.email, u.phone, u.department_id, u.position_id, u.status, u.version, u.created_at, u.updated_at FROM iam_user u JOIN iam_user_role ur ON ur.user_id = u.id AND ur.tenant_id = u.tenant_id WHERE ur.role_id = #{roleId} AND ur.status = 'ACTIVE' AND ur.active_slot = 1 AND u.delete_marker = 0
AND u.tenant_id = #{tenantId}
ORDER BY ur.created_at DESC

